class Solution {
  public int[][] cyclicShift(int n, int[][] grid, int[] rowShift, int[] colShift) {
    int[][] rows = new int[n][n];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) rows[i][(j - rowShift[i] + n) % n] = grid[i][j];
    }
    int[][] result = new int[n][n];
    for (int j = 0; j < n; j++) {
      for (int i = 0; i < n; i++) result[(i - colShift[j] + n) % n][j] = rows[i][j];
    }
    return result;
  }
}
